export const meta = {
  name: 'copycat-video-deconstruction',
  description: 'Analyze 4 screen recordings: extract frames, read them, reconstruct timelines',
  phases: [{ title: 'Analyze', detail: 'one agent per video, frame extraction + visual read' }],
}

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['app', 'purpose', 'timeline', 'observations', 'extractable_knowledge', 'open_questions'],
  properties: {
    app: { type: 'string', description: 'Which application(s)/website(s) are on screen' },
    purpose: { type: 'string', description: 'One-paragraph read of what the user is demonstrating' },
    timeline: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['time', 'event'],
        properties: {
          time: { type: 'string', description: 'e.g. 0:04' },
          event: { type: 'string', description: 'What visibly happens' },
        },
      },
    },
    observations: { type: 'array', items: { type: 'string' }, description: 'Notable UI details, exact text visible on screen, settings, values' },
    extractable_knowledge: { type: 'array', items: { type: 'string' }, description: 'Techniques/workflows/knowledge a copycat recipe could capture from this clip' },
    open_questions: { type: 'array', items: { type: 'string' }, description: 'Things that happened too fast or were ambiguous even after dense sampling' },
  },
}

phase('Analyze')
const results = await parallel(args.videos.map((v) => () =>
  agent(`Analyze a macOS screen recording by extracting frames and READING them visually. Be thorough — your job is to reconstruct exactly what the user does and sees.

Video: "${v.path}" (${v.duration}s, 2880x1864, 60fps, no audio)
Work directory (create it): ${v.outdir}

Steps:
1. mkdir -p "${v.outdir}"
2. Extract 1 frame per second, downscaled: ffmpeg -v error -i "${v.path}" -vf "fps=1,scale=1440:-2" "${v.outdir}/f_%03d.png"   (frame f_001 = t≈0s, f_002 = t≈1s, ...)
3. Read EVERY extracted frame in order with the Read tool (you can read several per turn). Track what changes frame to frame: which app/site, what's clicked, what's typed, menus, dialogs, scrolling, tab switches.
4. If something important happens between two frames (a fast dialog, a menu that flashes, a value that changed with no visible cause), re-extract that window densely, e.g.: ffmpeg -v error -ss <start> -to <end> -i "${v.path}" -vf "fps=6,scale=1440:-2" "${v.outdir}/dense_%03d.png" and read those too.
5. Transcribe exact on-screen text where it matters (titles, filenames, prompts, settings values, URLs, code). Precision beats paraphrase.

Return via StructuredOutput: the app(s), the purpose, a timestamped timeline of events, precise observations (exact text/values), what reusable knowledge/technique this clip demonstrates, and open questions for anything still ambiguous.`, { label: `analyze:${v.name}`, phase: 'Analyze', schema: SCHEMA })
))

return { videos: args.videos.map(v => v.name), results }

